        IF (SELECT count(*) FROM giving_records) <> (jsonb_array_length(COALESCE(snapshot->'giving', '[]'::jsonb))) THEN
            RAISE EXCEPTION 'Row count mismatch for giving_records';
        END IF;

        INSERT INTO announcements (sort_order, id, title, content, category, priority, is_active, published_date, expiry_date, extra_fields)
        SELECT ordinal - 1, record->>'id', CASE WHEN jsonb_typeof(record->'title') = 'string' THEN (record->>'title') END, CASE WHEN jsonb_typeof(record->'content') = 'string' THEN (record->>'content') END, CASE WHEN jsonb_typeof(record->'category') = 'string' THEN (record->>'category') END, CASE WHEN jsonb_typeof(record->'priority') = 'string' THEN (record->>'priority') END, CASE WHEN jsonb_typeof(record->'isActive') = 'boolean' THEN ((record->>'isActive')::boolean)::integer END, CASE WHEN jsonb_typeof(record->'publishedDate') = 'string' THEN (record->>'publishedDate') END, CASE WHEN jsonb_typeof(record->'expiryDate') = 'string' THEN (record->>'expiryDate') END, (record - 'id' - array_remove(ARRAY[CASE WHEN jsonb_typeof(record->'title') = 'string' THEN 'title' END, CASE WHEN jsonb_typeof(record->'content') = 'string' THEN 'content' END, CASE WHEN jsonb_typeof(record->'category') = 'string' THEN 'category' END, CASE WHEN jsonb_typeof(record->'priority') = 'string' THEN 'priority' END, CASE WHEN jsonb_typeof(record->'isActive') = 'boolean' THEN 'isActive' END, CASE WHEN jsonb_typeof(record->'publishedDate') = 'string' THEN 'publishedDate' END, CASE WHEN jsonb_typeof(record->'expiryDate') = 'string' THEN 'expiryDate' END]::text[], NULL))::text
        FROM jsonb_array_elements(COALESCE(snapshot->'announcements', '[]'::jsonb)) WITH ORDINALITY AS rows(record, ordinal);
        IF (SELECT count(*) FROM announcements) <> (jsonb_array_length(COALESCE(snapshot->'announcements', '[]'::jsonb))) THEN
            RAISE EXCEPTION 'Row count mismatch for announcements';
        END IF;

        INSERT INTO archived_events (sort_order, id, title, date, end_date, date_label, time, category, summary, content, image_src, source_url, extra_fields)
        SELECT ordinal - 1, record->>'id', CASE WHEN jsonb_typeof(record->'title') = 'string' THEN (record->>'title') END, CASE WHEN jsonb_typeof(record->'date') = 'string' THEN (record->>'date') END, CASE WHEN jsonb_typeof(record->'endDate') = 'string' THEN (record->>'endDate') END, CASE WHEN jsonb_typeof(record->'dateLabel') = 'string' THEN (record->>'dateLabel') END, CASE WHEN jsonb_typeof(record->'time') = 'string' THEN (record->>'time') END, CASE WHEN jsonb_typeof(record->'category') = 'string' THEN (record->>'category') END, CASE WHEN jsonb_typeof(record->'summary') = 'string' THEN (record->>'summary') END, CASE WHEN jsonb_typeof(record->'content') <> 'null' THEN (record->'content')::text END, CASE WHEN jsonb_typeof(record->'imageSrc') = 'string' THEN (record->>'imageSrc') END, CASE WHEN jsonb_typeof(record->'sourceUrl') = 'string' THEN (record->>'sourceUrl') END, (record - 'id' - array_remove(ARRAY[CASE WHEN jsonb_typeof(record->'title') = 'string' THEN 'title' END, CASE WHEN jsonb_typeof(record->'date') = 'string' THEN 'date' END, CASE WHEN jsonb_typeof(record->'endDate') = 'string' THEN 'endDate' END, CASE WHEN jsonb_typeof(record->'dateLabel') = 'string' THEN 'dateLabel' END, CASE WHEN jsonb_typeof(record->'time') = 'string' THEN 'time' END, CASE WHEN jsonb_typeof(record->'category') = 'string' THEN 'category' END, CASE WHEN jsonb_typeof(record->'summary') = 'string' THEN 'summary' END, CASE WHEN jsonb_typeof(record->'content') <> 'null' THEN 'content' END, CASE WHEN jsonb_typeof(record->'imageSrc') = 'string' THEN 'imageSrc' END, CASE WHEN jsonb_typeof(record->'sourceUrl') = 'string' THEN 'sourceUrl' END]::text[], NULL))::text
        FROM jsonb_array_elements(COALESCE(snapshot->'archiveEvents', '[]'::jsonb)) WITH ORDINALITY AS rows(record, ordinal);
        IF (SELECT count(*) FROM archived_events) <> (jsonb_array_length(COALESCE(snapshot->'archiveEvents', '[]'::jsonb))) THEN
            RAISE EXCEPTION 'Row count mismatch for archived_events';
        END IF;

        INSERT INTO recurring_programmes (sort_order, title, frequency, day, time, location, description, badge, extra_fields)
        SELECT ordinal - 1, CASE WHEN jsonb_typeof(record->'title') = 'string' THEN (record->>'title') END, CASE WHEN jsonb_typeof(record->'frequency') = 'string' THEN (record->>'frequency') END, CASE WHEN jsonb_typeof(record->'day') = 'string' THEN (record->>'day') END, CASE WHEN jsonb_typeof(record->'time') = 'string' THEN (record->>'time') END, CASE WHEN jsonb_typeof(record->'location') = 'string' THEN (record->>'location') END, CASE WHEN jsonb_typeof(record->'description') = 'string' THEN (record->>'description') END, CASE WHEN jsonb_typeof(record->'badge') = 'string' THEN (record->>'badge') END, (record - array_remove(ARRAY[CASE WHEN jsonb_typeof(record->'title') = 'string' THEN 'title' END, CASE WHEN jsonb_typeof(record->'frequency') = 'string' THEN 'frequency' END, CASE WHEN jsonb_typeof(record->'day') = 'string' THEN 'day' END, CASE WHEN jsonb_typeof(record->'time') = 'string' THEN 'time' END, CASE WHEN jsonb_typeof(record->'location') = 'string' THEN 'location' END, CASE WHEN jsonb_typeof(record->'description') = 'string' THEN 'description' END, CASE WHEN jsonb_typeof(record->'badge') = 'string' THEN 'badge' END]::text[], NULL))::text
        FROM jsonb_array_elements(COALESCE(snapshot->'recurringPrograms', '[]'::jsonb)) WITH ORDINALITY AS rows(record, ordinal);
        IF (SELECT count(*) FROM recurring_programmes) <> (jsonb_array_length(COALESCE(snapshot->'recurringPrograms', '[]'::jsonb))) THEN
            RAISE EXCEPTION 'Row count mismatch for recurring_programmes';
        END IF;

        INSERT INTO ministries (sort_order, id, name, category, leader_or_team, description, icon_name, extra_fields)
        SELECT ordinal - 1, record->>'id', CASE WHEN jsonb_typeof(record->'name') = 'string' THEN (record->>'name') END, CASE WHEN jsonb_typeof(record->'category') = 'string' THEN (record->>'category') END, CASE WHEN jsonb_typeof(record->'leaderOrTeam') = 'string' THEN (record->>'leaderOrTeam') END, CASE WHEN jsonb_typeof(record->'description') = 'string' THEN (record->>'description') END, CASE WHEN jsonb_typeof(record->'iconName') = 'string' THEN (record->>'iconName') END, (record - 'id' - array_remove(ARRAY[CASE WHEN jsonb_typeof(record->'name') = 'string' THEN 'name' END, CASE WHEN jsonb_typeof(record->'category') = 'string' THEN 'category' END, CASE WHEN jsonb_typeof(record->'leaderOrTeam') = 'string' THEN 'leaderOrTeam' END, CASE WHEN jsonb_typeof(record->'description') = 'string' THEN 'description' END, CASE WHEN jsonb_typeof(record->'iconName') = 'string' THEN 'iconName' END]::text[], NULL))::text
        FROM jsonb_array_elements(COALESCE(snapshot->'ministries', '[]'::jsonb)) WITH ORDINALITY AS rows(record, ordinal);
        IF (SELECT count(*) FROM ministries) <> (jsonb_array_length(COALESCE(snapshot->'ministries', '[]'::jsonb))) THEN
            RAISE EXCEPTION 'Row count mismatch for ministries';
        END IF;

        INSERT INTO live_stream_settings (id, status, stream_title, stream_subtitle, video_id_or_url, thumbnail_url, active_service_type, scheduled_time, preacher, theme, scripture, viewer_count, pinned_notice, enable_live_chat_notice, extra_fields)
        SELECT 1, CASE WHEN jsonb_typeof(record->'status') = 'string' THEN (record->>'status') END, CASE WHEN jsonb_typeof(record->'streamTitle') = 'string' THEN (record->>'streamTitle') END, CASE WHEN jsonb_typeof(record->'streamSubtitle') = 'string' THEN (record->>'streamSubtitle') END, CASE WHEN jsonb_typeof(record->'videoIdOrUrl') = 'string' THEN (record->>'videoIdOrUrl') END, CASE WHEN jsonb_typeof(record->'thumbnailUrl') = 'string' THEN (record->>'thumbnailUrl') END, CASE WHEN jsonb_typeof(record->'activeServiceType') = 'string' THEN (record->>'activeServiceType') END, CASE WHEN jsonb_typeof(record->'scheduledTime') = 'string' THEN (record->>'scheduledTime') END, CASE WHEN jsonb_typeof(record->'preacher') = 'string' THEN (record->>'preacher') END, CASE WHEN jsonb_typeof(record->'theme') = 'string' THEN (record->>'theme') END, CASE WHEN jsonb_typeof(record->'scripture') = 'string' THEN (record->>'scripture') END, CASE WHEN CASE WHEN jsonb_typeof(record->'viewerCount') = 'number' AND (record->>'viewerCount') ~ '^-?[0-9]+$' THEN (record->>'viewerCount')::numeric BETWEEN -9223372036854775808 AND 9223372036854775807 ELSE false END THEN (record->>'viewerCount')::bigint END, CASE WHEN jsonb_typeof(record->'pinnedNotice') = 'string' THEN (record->>'pinnedNotice') END, CASE WHEN jsonb_typeof(record->'enableLiveChatNotice') = 'boolean' THEN ((record->>'enableLiveChatNotice')::boolean)::integer END, (record - array_remove(ARRAY[CASE WHEN jsonb_typeof(record->'status') = 'string' THEN 'status' END, CASE WHEN jsonb_typeof(record->'streamTitle') = 'string' THEN 'streamTitle' END, CASE WHEN jsonb_typeof(record->'streamSubtitle') = 'string' THEN 'streamSubtitle' END, CASE WHEN jsonb_typeof(record->'videoIdOrUrl') = 'string' THEN 'videoIdOrUrl' END, CASE WHEN jsonb_typeof(record->'thumbnailUrl') = 'string' THEN 'thumbnailUrl' END, CASE WHEN jsonb_typeof(record->'activeServiceType') = 'string' THEN 'activeServiceType' END, CASE WHEN jsonb_typeof(record->'scheduledTime') = 'string' THEN 'scheduledTime' END, CASE WHEN jsonb_typeof(record->'preacher') = 'string' THEN 'preacher' END, CASE WHEN jsonb_typeof(record->'theme') = 'string' THEN 'theme' END, CASE WHEN jsonb_typeof(record->'scripture') = 'string' THEN 'scripture' END, CASE WHEN CASE WHEN jsonb_typeof(record->'viewerCount') = 'number' AND (record->>'viewerCount') ~ '^-?[0-9]+$' THEN (record->>'viewerCount')::numeric BETWEEN -9223372036854775808 AND 9223372036854775807 ELSE false END THEN 'viewerCount' END, CASE WHEN jsonb_typeof(record->'pinnedNotice') = 'string' THEN 'pinnedNotice' END, CASE WHEN jsonb_typeof(record->'enableLiveChatNotice') = 'boolean' THEN 'enableLiveChatNotice' END]::text[], NULL))::text
        FROM (SELECT snapshot->'liveStream' AS record WHERE snapshot ? 'liveStream') AS settings;
        IF (SELECT count(*) FROM live_stream_settings) <> (CASE WHEN snapshot ? 'liveStream' THEN 1 ELSE 0 END) THEN
            RAISE EXCEPTION 'Row count mismatch for live_stream_settings';
        END IF;

        INSERT INTO church_contact_settings (id, phone, directory_phone, email, sanctuary_address, mailing_address, youtube_url, facebook_url, zelle_email, sms_giving_number, office_hours, extra_fields)
        SELECT 1, CASE WHEN jsonb_typeof(record->'phone') = 'string' THEN (record->>'phone') END, CASE WHEN jsonb_typeof(record->'directoryPhone') = 'string' THEN (record->>'directoryPhone') END, CASE WHEN jsonb_typeof(record->'email') = 'string' THEN (record->>'email') END, CASE WHEN jsonb_typeof(record->'sanctuaryAddress') = 'string' THEN (record->>'sanctuaryAddress') END, CASE WHEN jsonb_typeof(record->'mailingAddress') = 'string' THEN (record->>'mailingAddress') END, CASE WHEN jsonb_typeof(record->'youtubeUrl') = 'string' THEN (record->>'youtubeUrl') END, CASE WHEN jsonb_typeof(record->'facebookUrl') = 'string' THEN (record->>'facebookUrl') END, CASE WHEN jsonb_typeof(record->'zelleEmail') = 'string' THEN (record->>'zelleEmail') END, CASE WHEN jsonb_typeof(record->'smsGivingNumber') = 'string' THEN (record->>'smsGivingNumber') END, CASE WHEN jsonb_typeof(record->'officeHours') = 'string' THEN (record->>'officeHours') END, (record - array_remove(ARRAY[CASE WHEN jsonb_typeof(record->'phone') = 'string' THEN 'phone' END, CASE WHEN jsonb_typeof(record->'directoryPhone') = 'string' THEN 'directoryPhone' END, CASE WHEN jsonb_typeof(record->'email') = 'string' THEN 'email' END, CASE WHEN jsonb_typeof(record->'sanctuaryAddress') = 'string' THEN 'sanctuaryAddress' END, CASE WHEN jsonb_typeof(record->'mailingAddress') = 'string' THEN 'mailingAddress' END, CASE WHEN jsonb_typeof(record->'youtubeUrl') = 'string' THEN 'youtubeUrl' END, CASE WHEN jsonb_typeof(record->'facebookUrl') = 'string' THEN 'facebookUrl' END, CASE WHEN jsonb_typeof(record->'zelleEmail') = 'string' THEN 'zelleEmail' END, CASE WHEN jsonb_typeof(record->'smsGivingNumber') = 'string' THEN 'smsGivingNumber' END, CASE WHEN jsonb_typeof(record->'officeHours') = 'string' THEN 'officeHours' END]::text[], NULL))::text
        FROM (SELECT snapshot->'churchContactConfig' AS record WHERE snapshot ? 'churchContactConfig') AS settings;
        IF (SELECT count(*) FROM church_contact_settings) <> (CASE WHEN snapshot ? 'churchContactConfig' THEN 1 ELSE 0 END) THEN
            RAISE EXCEPTION 'Row count mismatch for church_contact_settings';
        END IF;
        INSERT INTO site_state (id, version, last_backup_date)
        VALUES (1, snapshot_version + 1, COALESCE(snapshot->>'lastBackupDate', ''));
    END IF;

    ALTER TABLE dhog.site RENAME TO site_legacy_backup;
END;
$$;

COMMIT;
